#[derive(Clone)]
enum CompilerCallableFacts {
    Named {
        name: String,
        declarations: Vec<FunctionSource>,
        captures: Vec<CompilerContextCapture>,
    },
    Symbolic(CallableKind),
    Anonymous {
        parameters: Vec<AnonymousPattern>,
        body: Expression,
        captures: BTreeMap<String, BindingFacts>,
        static_context: bool,
        span: Span,
    },
}

impl CompilerDataMemberFacts {
    fn from_binding(facts: &BindingFacts, declaration_end: usize) -> Self {
        Self {
            storage_name: facts.storage_name.clone(),
            value_type: facts.value_type.clone(),
            int_range: facts.int_range.clone(),
            rational_value: facts.rational_value.clone(),
            infinity_negative: facts.infinity_negative,
            declaration_end,
        }
    }
}

#[derive(Clone, Default)]
struct StaticValueFacts {
    int_range: Option<IntRange>,
    rational_value: Option<BigRational>,
    string_value: Option<String>,
    callable: Option<CompilerCallableFacts>,
    tuple_fields: Vec<Self>,
    record_fields: BTreeMap<String, Self>,
    list_entries: Option<Vec<Self>>,
    array_entries: Option<Vec<Self>>,
    map_entries: Option<Vec<(String, Self)>>,
    optional: Option<CompilerOptionalFacts>,
    sum: Option<CompilerSumFacts>,
    result: Option<CompilerResultFacts>,
}

#[derive(Clone)]
enum CompilerOptionalFacts {
    None,
    Some(Box<StaticValueFacts>),
}

#[derive(Clone)]
struct CompilerSumFacts {
    alternative: u32,
    alternative_name: String,
    payload: Option<Box<StaticValueFacts>>,
}

#[derive(Clone)]
struct CompilerResultFacts {
    success: Box<StaticValueFacts>,
}

fn retain_static_value_facts(binding: &mut BindingFacts, value: &StaticValueFacts) {
    binding.int_range.clone_from(&value.int_range);
    binding.rational_value.clone_from(&value.rational_value);
    binding.string_value.clone_from(&value.string_value);
    binding.callable.clone_from(&value.callable);
    binding.tuple_fields.clone_from(&value.tuple_fields);
    binding.record_fields.clone_from(&value.record_fields);
    binding.list_entries.clone_from(&value.list_entries);
    binding.array_entries.clone_from(&value.array_entries);
    binding.map_entries.clone_from(&value.map_entries);
    binding.optional.clone_from(&value.optional);
    binding.sum.clone_from(&value.sum);
    binding.result.clone_from(&value.result);
}

fn present_optional_payload(facts: StaticValueFacts) -> Option<StaticValueFacts> {
    match facts.optional {
        Some(CompilerOptionalFacts::Some(payload)) => Some(*payload),
        Some(CompilerOptionalFacts::None) | None => None,
    }
}

struct Analyzer {
    source: SourceText,
    language_version: LanguageVersion,
    language_features: Vec<String>,
    enums: EnumTypes,
    enum_alternatives: EnumAlternativeBindings,
    sums: SumTypes,
    sum_alternatives: SumAlternativeBindings,
    modulars: ModularTypes,
    interfaces: InterfaceTypes,
    interface_implementations: Vec<CompilerInterfaceImplementation>,
    functions: BTreeMap<String, Vec<FunctionSource>>,
    generators: BTreeMap<String, Vec<GeneratorSource>>,
    task_types: TaskTypes,
    task_definitions: TaskDefinitions,
    external_metadata: BTreeMap<String, CompilerExternalMetadata>,
    external_locations: BTreeMap<String, CompilerLocation>,
    instances: Vec<CompilerFunction>,
    active_calls: Vec<String>,
    active_recursive_functions: BTreeMap<String, ActiveRecursiveFunction>,
    root_bindings: BTreeMap<String, CompilerDataMemberFacts>,
    anonymous_callables: BTreeMap<u32, CompilerCallableFacts>,
    anonymous_function_value_names: Vec<String>,
    anonymous_function_value_tags: BTreeMap<usize, u32>,
    nested_function_value_tags: BTreeMap<String, u32>,
    returned_function_values: BTreeMap<String, CompilerCallableFacts>,
    returned_aggregate_value_facts: BTreeMap<String, StaticValueFacts>,
    constraints: Vec<CompilerConstraint>,
    constraint_bindings: BTreeMap<String, u32>,
    constraint_binding_declarations: BTreeMap<String, usize>,
    in_function: bool,
    function_values_used: bool,
    consumed_generators: BTreeSet<String>,
    generator_values: BTreeMap<String, CompilerExpression>,
    returned_generator_values: BTreeMap<String, CompilerExpression>,
    static_context: bool,
    next_instance: usize,
    next_task_transaction: u64,
}

impl Analyzer {
    fn new(
        source: SourceText,
        language_version: LanguageVersion,
        language_features: Vec<String>,
        enums: EnumTypes,
        enum_alternatives: EnumAlternativeBindings,
        sums: SumTypes,
        sum_alternatives: SumAlternativeBindings,
    ) -> Self {
        Self {
            source,
            language_version,
            language_features,
            enums,
            enum_alternatives,
            sums,
            sum_alternatives,
            modulars: BTreeMap::new(),
            interfaces: BTreeMap::new(),
            interface_implementations: Vec::new(),
            functions: BTreeMap::new(),
            generators: BTreeMap::new(),
            task_types: BTreeMap::new(),
            task_definitions: BTreeMap::new(),
            external_metadata: BTreeMap::new(),
            external_locations: BTreeMap::new(),
            instances: Vec::new(),
            active_calls: Vec::new(),
            active_recursive_functions: BTreeMap::new(),
            root_bindings: BTreeMap::new(),
            anonymous_callables: BTreeMap::new(),
            anonymous_function_value_names: Vec::new(),
            anonymous_function_value_tags: BTreeMap::new(),
            nested_function_value_tags: BTreeMap::new(),
            returned_function_values: BTreeMap::new(),
            returned_aggregate_value_facts: BTreeMap::new(),
            constraints: Vec::new(),
            constraint_bindings: BTreeMap::new(),
            constraint_binding_declarations: BTreeMap::new(),
            in_function: false,
            function_values_used: false,
            consumed_generators: BTreeSet::new(),
            generator_values: BTreeMap::new(),
            returned_generator_values: BTreeMap::new(),
            static_context: false,
            next_instance: 0,
            next_task_transaction: 1,
        }
    }
}

/// Analyze the currently implemented native-compiler subset.
///
/// # Errors
///
/// Returns a shared source diagnostic for invalid or not-yet-supported input.
#[allow(clippy::too_many_lines)] // Root collection order keeps declaration visibility explicit.
pub fn analyze_for_compiler(text: &str) -> Result<CompilerProgram, Diagnostic> {
    let source = SourceText::new(text).map_err(|error| {
        Diagnostic::error(error.code, 1, 1, error.message).with_source_span(error.span)
    })?;
    let parsed = parse(&source, &lex(&source));
    if let Some(error) = parsed.diagnostics.first() {
        return Err(source_diagnostic(
            &source,
            error.code,
            error.span,
            error.message.clone(),
        ));
    }
    let (language_version, language_features) =
        compiler_language_context(&source, &parsed.statements)?;
    reject_later_language_selections(&source, &parsed.statements)?;

    let (enums, enum_alternatives) = collect_enums(&source, &parsed.statements)?;
    let (sums, sum_alternatives) =
        collect_sums(&source, &parsed.statements, &enums, &enum_alternatives)?;
    let modular_sources = collect_modular_sources(
        &source,
        &parsed.statements,
        &enums,
        &enum_alternatives,
        &sums,
        &sum_alternatives,
    )?;
    let interface_sources = collect_interface_sources(
        &source,
        &parsed.statements,
        &enums,
        &enum_alternatives,
        &sums,
        &sum_alternatives,
        &modular_sources,
    )?;
    let reserved_names = compiler_reserved_names(
        &source,
        &enums,
        &enum_alternatives,
        &sums,
        &sum_alternatives,
        &modular_sources,
        &interface_sources,
    );
    let mut analyzer = Analyzer::new(
        source.clone(),
        language_version,
        language_features,
        enums,
        enum_alternatives,
        sums,
        sum_alternatives,
    );
    analyzer.install_modular_types(&modular_sources)?;
    analyzer.install_interfaces(&interface_sources)?;
    analyzer.validate_interface_implementations(&parsed.statements)?;
    let (task_types, task_definitions) = collect_compiler_tasks(&source, &parsed.statements)?;
    analyzer.task_types = task_types;
    analyzer.task_definitions = task_definitions;
    collect_functions(
        &source,
        &parsed.statements,
        &reserved_names,
        &mut analyzer.functions,
    )?;
    collect_character_generators(
        &source,
        &parsed.statements,
        &reserved_names,
        &analyzer.enums,
        &analyzer.functions,
        &mut analyzer.generators,
    )?;
    let mut environment = BTreeMap::new();
    let main = analyzer.analyze_block(
        &parsed.statements,
        &mut environment,
        BlockKind::TopLevel,
        None,
    )?;
    require_runtime_main_result(&source, &main)?;
    let function_value_names = compiler_function_value_names(&mut analyzer);
    let interfaces = analyzer
        .interfaces
        .values()
        .map(|(interface, _)| interface.clone())
        .collect();
    let tasks = analyzer
        .task_definitions
        .values()
        .map(|definition| definition.task.clone())
        .collect();
    Ok(CompilerProgram {
        source,
        language_version,
        language_features: analyzer.language_features,
        main,
        function_value_names,
        constraints: analyzer.constraints,
        interfaces,
        interface_implementations: analyzer.interface_implementations,
        tasks,
        functions: analyzer.instances,
    })
}

#[allow(clippy::too_many_lines)] // The closed task boundary is validated in declaration order.
fn collect_compiler_tasks(
    source: &SourceText,
    statements: &[Statement],
) -> Result<(TaskTypes, TaskDefinitions), Diagnostic> {
    let mut task_types = BTreeMap::new();
    let mut task_definitions = BTreeMap::new();
    for statement in statements {
        if let Statement::Binding { name, value, .. } = statement
            && let Expression::Application { items, span } = value
            && let [
                Expression::Identifier(task),
                Expression::Product { fields, .. },
            ] = items.as_slice()
            && source.slice(*task) == "Task"
        {
            let classifier = source.slice(*name).to_owned();
            if task_types.contains_key(&classifier) {
                return Err(source_diagnostic(
                    source,
                    "E-DUPLICATE-BINDING",
                    *name,
                    format!("`{classifier}` is already declared in this scope"),
                ));
            }
            let mut identity = None;
            let mut queue_size = None;
            let mut option_names = BTreeSet::new();
            for field in fields {
                let Some(label) = field.label else {
                    return Err(source_diagnostic(
                        source,
                        "E-TASK-OPTIONS",
                        field.value.span(),
                        "Task options must be labeled",
                    ));
                };
                let option_name = source.slice(label);
                if !option_names.insert(option_name) {
                    return Err(source_diagnostic(
                        source,
                        "E-TASK-OPTIONS",
                        label,
                        format!("Task option `{option_name}` occurs more than once"),
                    ));
                }
                match option_name {
                    "identity" => {
                        let Expression::Identifier(value) = &field.value else {
                            return Err(source_diagnostic(
                                source,
                                "E-TASK-OPTIONS",
                                field.value.span(),
                                "Task identity must be a static identity",
                            ));
                        };
                        identity = Some(source.slice(*value).to_owned());
                    }
                    "queue-size" => {
                        let Expression::Integer(value) = &field.value else {
                            return Err(source_diagnostic(
                                source,
                                "E-TASK-OPTIONS",
                                field.value.span(),
                                "Task queue-size must be a static Nat",
                            ));
                        };
                        let value = parse_integer(source.slice(*value))
                            .and_then(|value| u64::try_from(value).ok());
                        queue_size = Some(value.ok_or_else(|| {
                            source_diagnostic(
                                source,
                                "E-TASK-OPTIONS",
                                field.value.span(),
                                "Task queue-size must fit an unsigned 64-bit Nat",
                            )
                        })?);
                    }
                    option => {
                        return Err(unsupported(
                            source,
                            label,
                            &format!("Task option `{option}`"),
                        ));
                    }
                }
            }
            let identity = identity.ok_or_else(|| {
                source_diagnostic(
                    source,
                    "E-TASK-OPTIONS",
                    *span,
                    "the native task increment requires an identity option",
                )
            })?;
            task_types.insert(
                classifier.clone(),
                TaskTypeSource {
                    classifier,
                    identity,
                    queue_size,
                    span: statement_span(statement),
                },
            );
            continue;
        }

        let Statement::Implementation {
            name,
            classifier,
            declarations,
            span,
        } = statement
        else {
            continue;
        };
        let Expression::Identifier(classifier_name) = classifier else {
            continue;
        };
        let Some(task_type) = task_types.get(source.slice(*classifier_name)).cloned() else {
            continue;
        };
        let definition = source.slice(*name).to_owned();
        if task_definitions.contains_key(&definition) {
            return Err(source_diagnostic(
                source,
                "E-DUPLICATE-BINDING",
                *name,
                format!("`{definition}` is already declared in this scope"),
            ));
        }
        let mut state = None;
        let mut handlers = BTreeMap::new();
        let mut public_handlers = Vec::new();
        for declaration in declarations {
            match declaration {
                Statement::StateField { name, classifier } => {
                    if state.is_some() || compact_classifier(source.slice(*classifier)) != "Nat" {
                        return Err(unsupported(
                            source,
                            statement_span(declaration),
                            "task state outside one private Nat field",
                        ));
                    }
                    state = Some(source.slice(*name).to_owned());
                }
                Statement::Function {
                    name,
                    is_static,
                    parameters,
                    result,
                    effect_bound,
                    clauses,
                    body,
                    span,
                } => {
                    if *is_static
                        || effect_bound.is_some()
                        || clauses.requires.is_some()
                        || clauses.effects.is_some()
                        || clauses.guarantees.is_some()
                        || clauses.result_binding.is_some()
                        || clauses.ensures.is_some()
                    {
                        return Err(unsupported(
                            source,
                            *span,
                            "task handler contracts or static dispatch",
                        ));
                    }
                    let handler_name = source.slice(*name).to_owned();
                    if handlers.contains_key(&handler_name) {
                        return Err(unsupported(source, *name, "overloaded task handler"));
                    }
                    let (kind, payload_type, response_type) = compiler_task_handler_shape(
                        source,
                        &handler_name,
                        parameters,
                        *result,
                        *span,
                    )?;
                    handlers.insert(
                        handler_name.clone(),
                        TaskHandlerSource {
                            name: handler_name.clone(),
                            parameters: parameters.clone(),
                            body: body.clone(),
                            span: *span,
                        },
                    );
                    public_handlers.push(CompilerTaskHandler {
                        name: handler_name,
                        payload_type,
                        response_type,
                        stream_type: None,
                        kind,
                        message_context_observable: false,
                    });
                }
                Statement::Generator {
                    name,
                    parameters,
                    yielded,
                    resumed,
                    result,
                    body,
                    span,
                } => {
                    let handler_name = source.slice(*name).to_owned();
                    if handlers.contains_key(&handler_name) {
                        return Err(unsupported(source, *name, "overloaded task handler"));
                    }
                    let (payload_type, stream_type) = compiler_task_stream_shape(
                        source,
                        &handler_name,
                        parameters,
                        *yielded,
                        *resumed,
                        *result,
                        *span,
                    )?;
                    handlers.insert(
                        handler_name.clone(),
                        TaskHandlerSource {
                            name: handler_name.clone(),
                            parameters: parameters.clone(),
                            body: body.clone(),
                            span: *span,
                        },
                    );
                    public_handlers.push(CompilerTaskHandler {
                        name: handler_name,
                        payload_type,
                        response_type: CompilerType::Unit,
                        stream_type: Some(stream_type),
                        kind: CompilerTaskHandlerKind::Stream,
                        message_context_observable: false,
                    });
                }
                _ => {
                    return Err(unsupported(
                        source,
                        statement_span(declaration),
                        "task implementation member",
                    ));
                }
            }
        }
        let state_name = state.ok_or_else(|| {
            source_diagnostic(
                source,
                "E-TASK-STATE-INITIALIZATION",
                *name,
                "the native task increment requires one private Nat state field",
            )
        })?;
        if !public_handlers.iter().any(|handler| {
            handler.name == "start" && handler.kind == CompilerTaskHandlerKind::Start
        }) {
            return Err(source_diagnostic(
                source,
                "E-TASK-START-REQUIRED",
                *name,
                "every task implementation requires a start handler",
            ));
        }
        let task = CompilerTaskType {
            classifier: task_type.classifier,
            definition: definition.clone(),
            identity: task_type.identity,
            queue_size: task_type.queue_size,
            state_name,
            state_type: Box::new(CompilerType::Nat),
            handlers: public_handlers,
            scheduler: CompilerTaskScheduler::DeterministicImmediateFifo,
        };
        validate_direct_task_handlers(source, &task, &handlers)?;
        task_definitions.insert(
            definition,
            TaskDefinitionSource {
                task,
                handlers,
                span: *span,
            },
        );
    }
    Ok((task_types, task_definitions))
}

fn compiler_task_stream_shape(
    source: &SourceText,
    name: &str,
    parameters: &[FunctionParameter],
    yielded: Span,
    resumed: Span,
    result: Span,
    span: Span,
) -> Result<(CompilerType, CompilerGeneratorType), Diagnostic> {
    let classifier =
        |parameter: &FunctionParameter| compact_classifier(source.slice(parameter.classifier));
    if matches!(name, "start" | "terminate")
        || !matches!(parameters, [context, payload]
        if source.slice(context.name) == "_"
            && classifier(context) == "MessageContext"
            && source.slice(payload.name) == "_"
            && classifier(payload) == "Unit")
        || compact_classifier(source.slice(yielded)) != "Nat"
        || compact_classifier(source.slice(resumed)) != "Unit"
        || compact_classifier(source.slice(result)) != "Result(Unit,())"
    {
        return Err(unsupported(
            source,
            span,
            "native direct task stream handler shape",
        ));
    }
    Ok((
        CompilerType::Unit,
        CompilerGeneratorType {
            yield_type: Box::new(CompilerType::Nat),
            resume_type: Box::new(CompilerType::Unit),
            result_type: Box::new(CompilerType::TaskResponse(Box::new(CompilerType::Unit))),
        },
    ))
}

fn compiler_task_handler_shape(
    source: &SourceText,
    name: &str,
    parameters: &[FunctionParameter],
    result: Span,
    span: Span,
) -> Result<(CompilerTaskHandlerKind, CompilerType, CompilerType), Diagnostic> {
    let parameter_classifier = |index: usize| {
        parameters
            .get(index)
            .map(|parameter| compact_classifier(source.slice(parameter.classifier)))
    };
    let result = compact_classifier(source.slice(result));
    let lifecycle_shape = match name {
        "start" => {
            parameters.len() == 1
                && parameter_classifier(0).as_deref() == Some("Nat")
                && result == "Completed"
        }
        "terminate" => {
            parameters.len() == 1
                && parameter_classifier(0).as_deref() == Some("String")
                && result == "Unit"
        }
        _ => true,
    };
    if !lifecycle_shape {
        return Err(unsupported(
            source,
            span,
            "native task lifecycle handler shape",
        ));
    }
    match name {
        "start"
            if parameters.len() == 1
                && parameter_classifier(0).as_deref() == Some("Nat")
                && result == "Completed" =>
        {
            Ok((
                CompilerTaskHandlerKind::Start,
                CompilerType::Nat,
                CompilerType::Completed,
            ))
        }
        "terminate"
            if parameters.len() == 1
                && parameter_classifier(0).as_deref() == Some("String")
                && result == "Unit" =>
        {
            Ok((
                CompilerTaskHandlerKind::Terminate,
                CompilerType::String,
                CompilerType::Unit,
            ))
        }
        _ if parameters.len() == 2
            && parameter_classifier(0).as_deref() == Some("MessageContext")
            && source.slice(parameters[0].name) == "_"
            && parameter_classifier(1).as_deref() == Some("Nat")
            && result == "Unit" =>
        {
            Ok((
                CompilerTaskHandlerKind::Event,
                CompilerType::Nat,
                CompilerType::Unit,
            ))
        }
        _ if parameters.len() == 2
            && parameter_classifier(0).as_deref() == Some("MessageContext")
            && source.slice(parameters[0].name) == "_"
            && parameter_classifier(1).as_deref() == Some("Unit")
            && result == "Result(Nat,())" =>
        {
            Ok((
                CompilerTaskHandlerKind::Request,
                CompilerType::Unit,
                CompilerType::Nat,
            ))
        }
        _ => Err(unsupported(
            source,
            span,
            "native direct task handler shape",
        )),
    }
}

fn validate_direct_task_handlers(
    source: &SourceText,
    task: &CompilerTaskType,
    handlers: &BTreeMap<String, TaskHandlerSource>,
) -> Result<(), Diagnostic> {
    for handler in handlers.values() {
        let kind = task
            .handlers
            .iter()
            .find(|candidate| candidate.name == handler.name)
            .expect("task metadata retains every handler")
            .kind;
        let valid = match kind {
            CompilerTaskHandlerKind::Start => matches!(
                handler.body.as_slice(),
                [
                    Statement::ContextAssignment { name, value: Expression::Identifier(value), .. },
                    Statement::Expression(Expression::Identifier(completed))
                ] if source.slice(*name) == task.state_name
                    && source.slice(*value) == source.slice(handler.parameters[0].name)
                    && source.slice(*completed) == "Completed"
            ),
            CompilerTaskHandlerKind::Event => matches!(
                handler.body.as_slice(),
                [Statement::ContextAssignment {
                    name,
                    value: Expression::Application { items, .. },
                    ..
                }] if source.slice(*name) == task.state_name
                    && matches!(items.as_slice(), [
                        Expression::ContextIdentifier(state),
                        Expression::Callable { kind: CallableKind::Plus, .. },
                        Expression::Identifier(amount)
                    ] if source.slice(*state) == task.state_name
                        && source.slice(*amount) == source.slice(handler.parameters[1].name))
            ),
            CompilerTaskHandlerKind::Request => matches!(
                handler.body.as_slice(),
                [Statement::Expression(Expression::ContextIdentifier(state))]
                    if source.slice(*state) == task.state_name
            ),
            CompilerTaskHandlerKind::Stream => matches!(
                handler.body.as_slice(),
                [
                    Statement::Expression(Expression::Application { items, .. }),
                    Statement::Expression(Expression::Unit(_))
                ] if matches!(items.as_slice(), [
                    Expression::Identifier(yield_name),
                    Expression::ContextIdentifier(state)
                ] if source.slice(*yield_name) == "yield"
                    && source.slice(*state) == task.state_name)
            ),
            CompilerTaskHandlerKind::Terminate => matches!(
                handler.body.as_slice(),
                [Statement::Expression(Expression::Unit(_))]
            ),
        };
        if !valid {
            return Err(unsupported(
                source,
                handler.span,
                &format!("task handler body `{}`", handler.name),
            ));
        }
    }
    Ok(())
}

fn compiler_language_context(
    source: &SourceText,
    statements: &[Statement],
) -> Result<(LanguageVersion, Vec<String>), Diagnostic> {
    let Some(Statement::LanguageSelection {
        version, features, ..
    }) = statements.first()
    else {
        return Err(source_diagnostic(
            source,
            "E-LANGUAGE-CONTEXT",
            Span::new(0, 0),
            "a source file begins with `use language ( version is v0.1 )`",
        ));
    };
    let language_version = source
        .slice(*version)
        .parse()
        .map_err(|message| source_diagnostic(source, "E-LANGUAGE-VERSION", *version, message))?;
    if language_version != LanguageVersion::DESIGN_0 {
        return Err(source_diagnostic(
            source,
            "E-COMPILER-UNSUPPORTED",
            *version,
            "the native compiler increment supports language version v0.1",
        ));
    }
    let mut language_features = BTreeSet::new();
    for feature in features {
        let feature_name = source.slice(*feature);
        if feature_name != "lint" {
            return Err(source_diagnostic(
                source,
                "E-COMPILER-UNSUPPORTED",
                *feature,
                format!(
                    "the native compiler increment does not support the `{feature_name}` language feature"
                ),
            ));
        }
        language_features.insert(feature_name.to_owned());
    }
    Ok((language_version, language_features.into_iter().collect()))
}

fn reject_later_language_selections(
    source: &SourceText,
    statements: &[Statement],
) -> Result<(), Diagnostic> {
    let Some(Statement::LanguageSelection { span, .. }) = statements
        .iter()
        .skip(1)
        .find(|statement| matches!(statement, Statement::LanguageSelection { .. }))
    else {
        return Ok(());
    };
    Err(unsupported(
        source,
        *span,
        "language-context change after the bootstrap selection",
    ))
}

fn require_runtime_main_result(
    source: &SourceText,
    main: &CompilerBlock,
) -> Result<(), Diagnostic> {
    if compiler_type_contains_static_only(&main.result.value_type)
        && !matches!(main.result.kind, CompilerExpressionKind::Capability(_))
    {
        Err(unsupported(
            source,
            main.result.span,
            "runtime observation of a static compiler value",
        ))
    } else if compiler_type_contains_external_location(&main.result.value_type) {
        Err(unsupported(
            source,
            main.result.span,
            "runtime observation of an external Location value",
        ))
    } else {
        Ok(())
    }
}

fn compiler_function_value_names(analyzer: &mut Analyzer) -> Vec<String> {
    if !analyzer.function_values_used {
        return Vec::new();
    }
    analyzer
        .functions
        .keys()
        .map(|name| format!("<fn {name}>"))
        .chain(
            COMPILER_SYMBOLIC_CALLABLES
                .iter()
                .map(|(_, name)| (*name).to_owned()),
        )
        .chain(std::mem::take(&mut analyzer.anonymous_function_value_names))
        .collect()
}

fn compiler_reserved_names(
    source: &SourceText,
    enums: &EnumTypes,
    enum_alternatives: &EnumAlternativeBindings,
    sums: &SumTypes,
    sum_alternatives: &SumAlternativeBindings,
    modulars: &[ModularSource],
    interfaces: &BTreeMap<String, InterfaceSource>,
) -> BTreeSet<String> {
    enums
        .keys()
        .chain(enum_alternatives.keys())
        .chain(sums.keys())
        .chain(sum_alternatives.keys())
        .cloned()
        .chain(
            modulars
                .iter()
                .map(|declaration| source.slice(declaration.name).to_owned()),
        )
        .chain(interfaces.keys().cloned())
        .chain(["root".to_owned()])
        .collect()
}

fn collect_enums(
    source: &SourceText,
    statements: &[Statement],
) -> Result<(EnumTypes, EnumAlternativeBindings), Diagnostic> {
    let mut enums = BTreeMap::new();
    let mut alternatives = BTreeMap::new();
    for statement in statements {
        let Some(declaration) = enum_declaration(source, statement) else {
            continue;
        };
        let EnumSource {
            name: name_span,
            alternatives: declarations,
            span: declaration_span,
        } = declaration;
        let name = source.slice(name_span).to_owned();
        if name == "root" || enums.contains_key(&name) || alternatives.contains_key(&name) {
            return Err(source_diagnostic(
                source,
                "E-DUPLICATE-BINDING",
                name_span,
                format!("`{name}` is already declared in this scope"),
            ));
        }
        let mut local = BTreeSet::new();
        for (label, alternative_span) in &declarations {
            if label == "root"
                || label == &name
                || !local.insert(label.clone())
                || enums.contains_key(label)
                || alternatives.contains_key(label)
            {
                return Err(source_diagnostic(
                    source,
                    "E-DUPLICATE-ENUM-ALTERNATIVE",
                    *alternative_span,
                    format!("enum alternative `{label}` is already declared in this scope"),
                ));
            }
        }
        let enumeration = CompilerEnumType {
            name: name.clone(),
            alternatives: declarations.into_iter().map(|(label, _)| label).collect(),
        };
        enums.insert(name, (enumeration.clone(), declaration_span));
        for (index, label) in enumeration.alternatives.iter().enumerate() {
            let index = u32::try_from(index).map_err(|_| {
                source_diagnostic(
                    source,
                    "E-COMPILER-UNSUPPORTED",
                    declaration_span,
                    "an Enum has more alternatives than the native tag can represent",
                )
            })?;
            alternatives.insert(
                label.clone(),
                (enumeration.clone(), index, declaration_span),
            );
        }
    }
    Ok((enums, alternatives))
}

fn enum_declaration(source: &SourceText, statement: &Statement) -> Option<EnumSource> {
    let Statement::Binding {
        name,
        classifier: None,
        value,
    } = (match statement {
        Statement::Published { declaration, .. } => declaration.as_ref(),
        statement => statement,
    })
    else {
        return None;
    };
    let Expression::Application { items, span } = value else {
        return None;
    };
    let [
        Expression::Identifier(constructor),
        Expression::Product { fields, .. },
    ] = items.as_slice()
    else {
        return None;
    };
    if source.slice(*constructor) != "Enum" {
        return None;
    }
    let alternatives = fields
        .iter()
        .map(|field| {
            let Expression::Identifier(alternative) = &field.value else {
                return None;
            };
            field
                .label
                .is_none()
                .then(|| (source.slice(*alternative).to_owned(), *alternative))
        })
        .collect::<Option<Vec<_>>>()?;
    Some(EnumSource {
        name: *name,
        alternatives,
        span: Span::new(name.start, span.end),
    })
}

fn sum_declaration(source: &SourceText, statement: &Statement) -> Option<SumSource> {
    let statement = match statement {
        Statement::Published { declaration, .. } => declaration.as_ref(),
        statement => statement,
    };
    if let Statement::Union {
        name,
        alternatives,
        span,
    } = statement
    {
        return Some(SumSource {
            name: *name,
            positional: false,
            alternatives: alternatives
                .iter()
                .map(|alternative| {
                    (
                        source.slice(alternative.name).to_owned(),
                        alternative.classifier,
                        alternative.name,
                    )
                })
                .collect(),
            span: *span,
        });
    }
    let Statement::Binding {
        name,
        classifier: None,
        value: Expression::Application { items, span },
    } = statement
    else {
        return None;
    };
    let [
        Expression::Identifier(constructor),
        Expression::Product { fields, .. },
    ] = items.as_slice()
    else {
        return None;
    };
    if source.slice(*constructor) != "Variant" || fields.iter().any(|field| field.label.is_some()) {
        return None;
    }
    Some(SumSource {
        name: *name,
        positional: true,
        alternatives: fields
            .iter()
            .enumerate()
            .map(|(index, field)| {
                (
                    format!("at {index}"),
                    Some(field.value.span()),
                    field.value.span(),
                )
            })
            .collect(),
        span: Span::new(name.start, span.end),
    })
}

fn modular_declaration(source: &SourceText, statement: &Statement) -> Option<ModularSource> {
    let statement = match statement {
        Statement::Published { declaration, .. } => declaration.as_ref(),
        statement => statement,
    };
    let Statement::Binding {
        name,
        classifier: None,
        value: Expression::Application { items, span },
    } = statement
    else {
        return None;
    };
    let [Expression::Identifier(kind), range] = items.as_slice() else {
        return None;
    };
    let signed = match source.slice(*kind) {
        "ModNat" => false,
        "ModInt" => true,
        _ => return None,
    };
    Some(ModularSource {
        name: *name,
        signed,
        range: range.clone(),
        span: Span::new(name.start, span.end),
    })
}

fn interface_declaration(statement: &Statement) -> Option<InterfaceSource> {
    let statement = match statement {
        Statement::Published { declaration, .. } => declaration.as_ref(),
        statement => statement,
    };
    let Statement::Interface {
        name,
        functions,
        span,
    } = statement
    else {
        return None;
    };
    Some(InterfaceSource {
        name: *name,
        functions: functions.clone(),
        span: *span,
    })
}

#[allow(clippy::too_many_arguments)] // Every existing nominal root namespace is a collision boundary.
fn collect_interface_sources(
    source: &SourceText,
    statements: &[Statement],
    enums: &EnumTypes,
    enum_alternatives: &EnumAlternativeBindings,
    sums: &SumTypes,
    sum_alternatives: &SumAlternativeBindings,
    modulars: &[ModularSource],
) -> Result<BTreeMap<String, InterfaceSource>, Diagnostic> {
    let modular_names = modulars
        .iter()
        .map(|declaration| source.slice(declaration.name))
        .collect::<BTreeSet<_>>();
    let mut interfaces = BTreeMap::new();
    for statement in statements {
        let Some(declaration) = interface_declaration(statement) else {
            continue;
        };
        let name = source.slice(declaration.name).to_owned();
        if name == "root"
            || enums.contains_key(&name)
            || enum_alternatives.contains_key(&name)
            || sums.contains_key(&name)
            || sum_alternatives.contains_key(&name)
            || modular_names.contains(name.as_str())
            || interfaces.contains_key(&name)
        {
            return Err(source_diagnostic(
                source,
                "E-DUPLICATE-DECLARATION",
                declaration.name,
                format!("`{name}` is already declared"),
            ));
        }
        let mut operations = BTreeSet::new();
        for function in &declaration.functions {
            let operation = source.slice(function.name);
            if !operations.insert(operation) {
                return Err(source_diagnostic(
                    source,
                    "E-DUPLICATE-INTERFACE-OPERATION",
                    function.name,
                    format!("interface operation `{operation}` is declared twice"),
                ));
            }
        }
        interfaces.insert(name, declaration);
    }
    Ok(interfaces)
}

fn collect_modular_sources(
    source: &SourceText,
    statements: &[Statement],
    enums: &EnumTypes,
    enum_alternatives: &EnumAlternativeBindings,
    sums: &SumTypes,
    sum_alternatives: &SumAlternativeBindings,
) -> Result<Vec<ModularSource>, Diagnostic> {
    let mut declarations = Vec::new();
    let mut names = BTreeSet::new();
    for statement in statements {
        let Some(mut declaration) = modular_declaration(source, statement) else {
            continue;
        };
        let name = source.slice(declaration.name);
        if name == "root"
            || enums.contains_key(name)
            || enum_alternatives.contains_key(name)
            || sums.contains_key(name)
            || sum_alternatives.contains_key(name)
            || !names.insert(name.to_owned())
        {
            return Err(source_diagnostic(
                source,
                "E-DUPLICATE-BINDING",
                declaration.name,
                format!("`{name}` is already declared in this scope"),
            ));
        }
        declaration.range = resolve_modular_range_source(
            source,
            statements,
            &declaration.range,
            declaration.name.start,
        );
        declarations.push(declaration);
    }
    Ok(declarations)
}

fn resolve_modular_range_source(
    source: &SourceText,
    statements: &[Statement],
    range: &Expression,
    mut before: usize,
) -> Expression {
    let mut range = range.clone();
    let mut seen = BTreeSet::new();
    while let Expression::Identifier(name) = &range {
        let name = source.slice(*name);
        if !seen.insert(name.to_owned()) {
            break;
        }
        let Some((value, declaration_start)) = statements.iter().rev().find_map(|statement| {
            let statement = match statement {
                Statement::Published { declaration, .. } => declaration.as_ref(),
                statement => statement,
            };
            let Statement::Binding {
                name: candidate,
                value,
                ..
            } = statement
            else {
                return None;
            };
            (candidate.start < before && source.slice(*candidate) == name)
                .then_some((value.clone(), candidate.start))
        }) else {
            break;
        };
        range = value;
        before = declaration_start;
    }
    range
}

fn collect_sums(
    source: &SourceText,
    statements: &[Statement],
    enums: &EnumTypes,
    enum_alternatives: &EnumAlternativeBindings,
) -> Result<(SumTypes, SumAlternativeBindings), Diagnostic> {
    let mut sums: SumTypes = BTreeMap::new();
    let mut alternatives: SumAlternativeBindings = BTreeMap::new();
    for statement in statements {
        let Some(declaration) = sum_declaration(source, statement) else {
            continue;
        };
        let name = source.slice(declaration.name).to_owned();
        if name == "root"
            || enums.contains_key(&name)
            || enum_alternatives.contains_key(&name)
            || sums.contains_key(&name)
            || alternatives.contains_key(&name)
        {
            return Err(source_diagnostic(
                source,
                "E-DUPLICATE-UNION",
                declaration.name,
                format!("`{name}` is already declared in this scope"),
            ));
        }
        let mut local = BTreeSet::new();
        let mut lowered = Vec::with_capacity(declaration.alternatives.len());
        for (label, classifier, alternative_span) in &declaration.alternatives {
            if !local.insert(label.clone()) {
                return Err(source_diagnostic(
                    source,
                    "E-DUPLICATE-UNION-ALTERNATIVE",
                    *alternative_span,
                    format!("sum alternative `{label}` occurs more than once"),
                ));
            }
            if !declaration.positional
                && (label == "root"
                    || label == &name
                    || enums.contains_key(label)
                    || enum_alternatives.contains_key(label)
                    || sums.contains_key(label)
                    || alternatives.contains_key(label))
            {
                return Err(source_diagnostic(
                    source,
                    "E-DUPLICATE-UNION-ALTERNATIVE",
                    *alternative_span,
                    format!("sum alternative `{label}` is already declared in this scope"),
                ));
            }
            let payload = classifier
                .map(|classifier| {
                    let classifier_text = compact_classifier(source.slice(classifier));
                    enums
                        .get(&classifier_text)
                        .filter(|(_, declaration)| declaration.end <= classifier.start)
                        .map(|(enumeration, _)| CompilerType::Enum(enumeration.clone()))
                        .or_else(|| {
                            sums.get(&classifier_text)
                                .filter(|(_, declaration)| declaration.end <= classifier.start)
                                .map(|(sum, _)| CompilerType::Sum(sum.clone()))
                        })
                        .or_else(|| parse_compact_classifier(&classifier_text))
                        .ok_or_else(|| unsupported(source, classifier, "sum payload classifier"))
                })
                .transpose()?;
            if payload.as_ref().is_some_and(|payload| {
                payload != &CompilerType::Function && !compiler_function_result_supported(payload)
            }) {
                return Err(unsupported(
                    source,
                    classifier.expect("unsupported payload has a classifier"),
                    "sum payload without an admitted private representation",
                ));
            }
            lowered.push(CompilerSumAlternative {
                name: label.clone(),
                payload,
            });
        }
        let sum = CompilerSumType {
            name: name.clone(),
            positional: declaration.positional,
            alternatives: lowered,
        };
        if !sum.positional {
            for (index, alternative) in sum.alternatives.iter().enumerate() {
                let index = u32::try_from(index).map_err(|_| {
                    unsupported(source, declaration.span, "native Union alternative tag")
                })?;
                alternatives.insert(
                    alternative.name.clone(),
                    (sum.clone(), index, declaration.span),
                );
            }
        }
        sums.insert(name, (sum, declaration.span));
    }
    Ok((sums, alternatives))
}

fn constraint_definition<'a>(
    source: &SourceText,
    expression: &'a Expression,
) -> Option<(Span, &'a [AnonymousPattern], &'a Expression, Span)> {
    let Expression::Application { items, span } = expression else {
        return None;
    };
    let [
        Expression::Identifier(base),
        Expression::Identifier(operation),
        Expression::AnonymousFunction {
            parameters, body, ..
        },
    ] = items.as_slice()
    else {
        return None;
    };
    (source.slice(*operation) == "constraint").then_some((
        *base,
        parameters.as_slice(),
        body.as_ref(),
        *span,
    ))
}

fn collect_functions(
    source: &SourceText,
    statements: &[Statement],
    reserved_names: &BTreeSet<String>,
    functions: &mut BTreeMap<String, Vec<FunctionSource>>,
) -> Result<(), Diagnostic> {
    for statement in statements {
        if let Statement::InterfaceImplementation { declarations, .. } = statement {
            collect_functions(source, declarations, reserved_names, functions)?;
            continue;
        }
        let declaration = match statement {
            Statement::Function {
                name,
                parameters,
                result,
                body,
                span,
                is_static,
                effect_bound,
                clauses,
            } if **clauses == FunctionClauses::default() => Some(FunctionSource {
                name: *name,
                parameters: parameters.clone(),
                result: *result,
                effect_bound: *effect_bound,
                declared_effects: None,
                body: body.clone(),
                span: *span,
                is_static: *is_static,
            }),
            Statement::Published { declaration, .. } => {
                if let Statement::Function {
                    name,
                    parameters,
                    result,
                    body,
                    span,
                    is_static,
                    effect_bound,
                    clauses,
                } = declaration.as_ref()
                    && **clauses == FunctionClauses::default()
                {
                    Some(FunctionSource {
                        name: *name,
                        parameters: parameters.clone(),
                        result: *result,
                        effect_bound: *effect_bound,
                        declared_effects: None,
                        body: body.clone(),
                        span: *span,
                        is_static: *is_static,
                    })
                } else if interface_declaration(statement).is_some()
                    || enum_declaration(source, statement).is_some()
                    || sum_declaration(source, statement).is_some()
                    || matches!(declaration.as_ref(), Statement::Binding { .. })
                {
                    None
                } else {
                    return Err(unsupported(
                        source,
                        statement_span(statement),
                        "published declaration",
                    ));
                }
            }
            Statement::Function { .. } => {
                return Err(unsupported(
                    source,
                    statement_span(statement),
                    "constrained or effectful function",
                ));
            }
            _ => None,
        };
        if let Some(mut function) = declaration {
            function.declared_effects =
                compiler_declared_effect_row(source, function.effect_bound)?;
            let name = source.slice(function.name).to_owned();
            if reserved_names.contains(&name) {
                return Err(source_diagnostic(
                    source,
                    "E-DUPLICATE-BINDING",
                    function.name,
                    format!("`{name}` is already declared in this scope"),
                ));
            }
            let overloads = functions.entry(name.clone()).or_default();
            if overloads
                .iter()
                .any(|candidate| same_function_input_header(source, candidate, &function))
            {
                return Err(source_diagnostic(
                    source,
                    "E-DUPLICATE-FUNCTION-OVERLOAD",
                    statement_span(statement),
                    format!("function `{name}` repeats an input signature and staticness"),
                ));
            }
            overloads.push(function);
        }
    }
    Ok(())
}

fn exact_character_generator_close_handler(
    source: &SourceText,
    initial: Span,
    body: &[Statement],
) -> Option<CompilerGeneratorCloseHandler> {
    let [
        Statement::Binding {
            name: result_binding,
            classifier: None,
            value: Expression::Application {
                items: yield_items, ..
            },
        },
        Statement::Expression(Expression::DecisionTable {
            subject,
            rules,
            span,
        }),
    ] = body
    else {
        return None;
    };
    let [
        Expression::Identifier(yield_operation),
        Expression::Identifier(yielded),
    ] = yield_items.as_slice()
    else {
        return None;
    };
    let Expression::Identifier(subject) = subject.as_ref() else {
        return None;
    };
    if source.slice(*yield_operation) != "yield"
        || source.slice(*yielded) != source.slice(initial)
        || source.slice(*subject) != source.slice(*result_binding)
        || source.slice(*result_binding) == "_"
        || source.slice(*result_binding) == source.slice(initial)
    {
        return None;
    }
    let mut error = None;
    let mut ok = None;
    let mut error_codes = Vec::new();
    for rule in rules {
        let Expression::Unit(action_span) = &rule.action else {
            return None;
        };
        let action = unit_expression(*action_span);
        match &rule.matcher {
            DecisionMatcher::Result {
                error: true,
                binding,
                ..
            } if error.is_none() && source.slice(*binding) != "_" => {
                error = Some((*binding, action));
            }
            DecisionMatcher::Result {
                error: false,
                binding,
                ..
            } if ok.is_none() && source.slice(*binding) != "_" => {
                ok = Some((*binding, action));
            }
            DecisionMatcher::ErrorCode {
                namespace,
                vocabulary,
                code,
                ..
            } if error.is_none() && error_codes.is_empty() => {
                let (_, code) = generator_error_code(
                    source.slice(*namespace),
                    source.slice(*vocabulary),
                    source.slice(*code),
                )?;
                error_codes.push(CompilerErrorCodeRule {
                    code,
                    action,
                    span: rule.span,
                });
            }
            _ => return None,
        }
    }
    let (error_binding, error_action) = error?;
    let (ok_binding, ok_action) = ok?;
    let (error_code_type, _) = generator_error_code("lang", "generator", "generator-closed")?;
    Some(CompilerGeneratorCloseHandler {
        result_binding: source.slice(*result_binding).to_owned(),
        result_binding_span: *result_binding,
        error_codes,
        error_binding: source.slice(error_binding).to_owned(),
        error_binding_span: error_binding,
        error_action: Box::new(error_action),
        ok_binding: source.slice(ok_binding).to_owned(),
        ok_binding_span: ok_binding,
        ok_action: Box::new(ok_action),
        error_code_type,
        span: *span,
    })
}

fn exact_generator_local_close_call(
    source: &SourceText,
    expression: &Expression,
    alternative: &str,
    value: u32,
    enumeration: &CompilerEnumType,
) -> Option<CompilerExpression> {
    let Expression::Application { items, span } = expression else {
        return None;
    };
    let [
        Expression::Identifier(function),
        Expression::Identifier(argument),
    ] = items.as_slice()
    else {
        return None;
    };
    if source.slice(*function) != "cleanup" || source.slice(*argument) != alternative {
        return None;
    }
    Some(CompilerExpression {
        kind: CompilerExpressionKind::Call {
            symbol: String::new(),
            arguments: vec![CompilerExpression {
                kind: CompilerExpressionKind::Enum(value),
                value_type: CompilerType::Enum(enumeration.clone()),
                int_range: None,
                rational_value: None,
                span: *argument,
            }],
        },
        value_type: CompilerType::Unit,
        int_range: None,
        rational_value: None,
        span: *span,
    })
}

#[allow(clippy::too_many_lines)] // Exact restored declaration and close branches form one proof.
fn exact_character_generator_local_close_handler(
    source: &SourceText,
    initial: Span,
    body: &[Statement],
    span: Span,
) -> Result<(CompilerGeneratorCloseHandler, CompilerFunction), Diagnostic> {
    let [
        enum_statement,
        function_statement,
        binding_statement,
        decision_statement,
    ] = body
    else {
        return Err(unsupported(
            source,
            span,
            "generator-local close body outside one enum, function, bound yield, and Result decision",
        ));
    };
    let Some(EnumSource {
        name: enum_name,
        alternatives,
        ..
    }) = enum_declaration(source, enum_statement)
    else {
        return Err(unsupported(source, span, "generator-local close enum"));
    };
    if source.slice(enum_name) != "CloseChoice"
        || alternatives.len() != 2
        || alternatives[0].0 != "Closed"
        || alternatives[1].0 != "Continued"
    {
        return Err(unsupported(
            source,
            enum_name,
            "generator-local close enum outside CloseChoice (Closed, Continued)",
        ));
    }
    let enumeration = CompilerEnumType {
        name: String::from("CloseChoice"),
        alternatives: vec![String::from("Closed"), String::from("Continued")],
    };

    let Statement::Function {
        name: function_name,
        is_static: false,
        parameters,
        result,
        effect_bound: None,
        clauses,
        body: function_body,
        span: function_span,
    } = function_statement
    else {
        return Err(unsupported(
            source,
            statement_span(function_statement),
            "generator-local close function declaration",
        ));
    };
    let [function_parameter] = parameters.as_slice() else {
        return Err(unsupported(
            source,
            *function_span,
            "generator-local close function arity",
        ));
    };
    if source.slice(*function_name) != "cleanup"
        || !function_parameter.fields.is_empty()
        || function_parameter.default.is_some()
        || function_parameter.qualifier.is_some()
        || source.slice(function_parameter.name) != "choice"
        || source.slice(function_parameter.classifier) != "CloseChoice"
        || source.slice(*result) != "Unit"
        || **clauses != FunctionClauses::default()
    {
        return Err(unsupported(
            source,
            *function_span,
            "generator-local close function outside cleanup (choice : CloseChoice) -> Unit",
        ));
    }
    let [Statement::Expression(Expression::Unit(function_result_span))] = function_body.as_slice()
    else {
        return Err(unsupported(
            source,
            *function_span,
            "generator-local cleanup body outside Unit",
        ));
    };

    let Statement::Binding {
        name: result_binding,
        classifier: None,
        value: Expression::Application {
            items: yield_items, ..
        },
    } = binding_statement
    else {
        return Err(unsupported(
            source,
            statement_span(binding_statement),
            "generator-local close result binding",
        ));
    };
    let [
        Expression::Identifier(yield_operation),
        Expression::Identifier(yielded),
    ] = yield_items.as_slice()
    else {
        return Err(unsupported(
            source,
            statement_span(binding_statement),
            "generator-local close yield",
        ));
    };
    if source.slice(*yield_operation) != "yield"
        || source.slice(*yielded) != source.slice(initial)
        || source.slice(*result_binding) != "resume-result"
        || source.slice(*result_binding) == source.slice(initial)
    {
        return Err(unsupported(
            source,
            statement_span(binding_statement),
            "generator-local close outside resume-result is yield initial",
        ));
    }

    let Statement::Expression(Expression::DecisionTable {
        subject,
        rules,
        span: decision_span,
    }) = decision_statement
    else {
        return Err(unsupported(
            source,
            statement_span(decision_statement),
            "generator-local close Result decision",
        ));
    };
    let Expression::Identifier(subject_name) = subject.as_ref() else {
        return Err(unsupported(
            source,
            subject.span(),
            "generator-local close Result subject",
        ));
    };
    let [closed_rule, error_rule, ok_rule] = rules.as_slice() else {
        return Err(unsupported(
            source,
            *decision_span,
            "generator-local close Result branches",
        ));
    };
    let (
        DecisionMatcher::ErrorCode {
            namespace,
            vocabulary,
            code,
            ..
        },
        DecisionMatcher::Result {
            error: true,
            binding: error_binding,
            ..
        },
        DecisionMatcher::Result {
            error: false,
            binding: ok_binding,
            ..
        },
    ) = (&closed_rule.matcher, &error_rule.matcher, &ok_rule.matcher)
    else {
        return Err(unsupported(
            source,
            *decision_span,
            "generator-local close Result branch order",
        ));
    };
    if source.slice(*subject_name) != source.slice(*result_binding)
        || source.slice(*namespace) != "lang"
        || source.slice(*vocabulary) != "generator"
        || source.slice(*code) != "generator-closed"
        || source.slice(*error_binding) != "problem"
        || source.slice(*ok_binding) != "resumed"
    {
        return Err(unsupported(
            source,
            *decision_span,
            "generator-local close outside the retained qualified Result branches",
        ));
    }
    let closed_action =
        exact_generator_local_close_call(source, &closed_rule.action, "Closed", 0, &enumeration)
            .ok_or_else(|| {
                unsupported(
                    source,
                    closed_rule.action.span(),
                    "generator-local close action outside cleanup Closed",
                )
            })?;
    let Expression::Unit(error_action_span) = &error_rule.action else {
        return Err(unsupported(
            source,
            error_rule.action.span(),
            "generator-local fallback close action outside Unit",
        ));
    };
    let ok_action =
        exact_generator_local_close_call(source, &ok_rule.action, "Continued", 1, &enumeration)
            .ok_or_else(|| {
                unsupported(
                    source,
                    ok_rule.action.span(),
                    "generator-local successful-resume action outside cleanup Continued",
                )
            })?;
    let (error_code_type, code) = generator_error_code("lang", "generator", "generator-closed")
        .expect("the intrinsic generator close code exists");
    let local_parameter = CompilerParameter {
        name: String::from("choice"),
        discarded: false,
        source_visible: true,
        value_type: CompilerType::Enum(enumeration),
        int_range: None,
        span: function_parameter.name,
    };
    Ok((
        CompilerGeneratorCloseHandler {
            result_binding: String::from("resume-result"),
            result_binding_span: *result_binding,
            error_codes: vec![CompilerErrorCodeRule {
                code,
                action: closed_action,
                span: closed_rule.span,
            }],
            error_binding: String::from("problem"),
            error_binding_span: *error_binding,
            error_action: Box::new(unit_expression(*error_action_span)),
            ok_binding: String::from("resumed"),
            ok_binding_span: *ok_binding,
            ok_action: Box::new(ok_action),
            error_code_type,
            span: *decision_span,
        },
        CompilerFunction {
            source_name: String::from("cleanup"),
            symbol: String::new(),
            parameters: vec![local_parameter],
            pattern_identities: Vec::new(),
            result_type: CompilerType::Unit,
            result_captures: Vec::new(),
            body: CompilerBlock {
                statements: Vec::new(),
                result: unit_expression(*function_result_span),
            },
            span: *function_span,
            is_static: false,
            declared_effects: None,
        },
    ))
}

#[allow(clippy::too_many_lines)] // The exact prefix and yield shape is rejected as one atomic proof.
fn exact_string_input_generator_body(
    source: &SourceText,
    parameter: &FunctionParameter,
    body: &[Statement],
    span: Span,
) -> Result<(CompilerBlock, Vec<String>), Diagnostic> {
    let [
        Statement::Binding {
            name: binding_name,
            classifier: Some(binding_classifier),
            value:
                Expression::Application {
                    items: predicate_items,
                    span: predicate_span,
                },
        },
        Statement::Discard {
            value: Expression::Application {
                items: yield_items, ..
            },
            ..
        },
        Statement::Expression(Expression::Unit(final_span)),
    ] = body
    else {
        return Err(unsupported(
            source,
            span,
            "String-input custom generator outside one empty? binding followed by one Character yield",
        ));
    };
    let [
        Expression::Identifier(predicate),
        Expression::Identifier(predicate_operand),
    ] = predicate_items.as_slice()
    else {
        return Err(unsupported(
            source,
            span,
            "String-input custom generator predicate outside empty? initial",
        ));
    };
    let [
        Expression::Identifier(yield_operation),
        Expression::String(yield_literal),
    ] = yield_items.as_slice()
    else {
        return Err(unsupported(
            source,
            span,
            "String-input custom generator yield outside one Character literal",
        ));
    };
    if source.slice(*binding_name) == "_"
        || source.slice(*binding_name) == source.slice(parameter.name)
        || source.slice(*binding_classifier) != "Boolean"
        || source.slice(*predicate) != "empty?"
        || source.slice(*predicate_operand) != source.slice(parameter.name)
        || source.slice(*yield_operation) != "yield"
    {
        return Err(unsupported(
            source,
            span,
            "String-input custom generator outside one named Boolean empty? initial binding",
        ));
    }
    let character = parse_string(source.slice(*yield_literal)).ok_or_else(|| {
        source_diagnostic(
            source,
            "E-STRING-LITERAL",
            *yield_literal,
            "invalid string literal delimiter",
        )
    })?;
    let count = character_count(character);
    if count != 1 {
        return Err(source_diagnostic(
            source,
            "E-CHARACTER-CLASSIFIER",
            *yield_literal,
            format!(
                "Character requires exactly one user-perceived character, but this String contains {count}"
            ),
        ));
    }
    let initial = CompilerExpression {
        kind: CompilerExpressionKind::Local(source.slice(parameter.name).to_owned()),
        value_type: CompilerType::String,
        int_range: None,
        rational_value: None,
        span: parameter.name,
    };
    let predicate = CompilerExpression {
        kind: CompilerExpressionKind::StringEmptyPredicate(Box::new(initial)),
        value_type: CompilerType::Boolean,
        int_range: None,
        rational_value: None,
        span: *predicate_span,
    };
    let binding_name_text = source.slice(*binding_name).to_owned();
    Ok((
        CompilerBlock {
            statements: vec![CompilerStatement::Binding(CompilerBinding {
                name: binding_name_text.clone(),
                storage_name: binding_name_text,
                value: predicate,
                span: *binding_name,
            })],
            result: unit_expression(*final_span),
        },
        vec![character.to_owned()],
    ))
}

fn exact_string_literal_expression(
    source: &SourceText,
    literal: Span,
) -> Result<CompilerExpression, Diagnostic> {
    let value = parse_string(source.slice(literal)).ok_or_else(|| {
        source_diagnostic(
            source,
            "E-STRING-LITERAL",
            literal,
            "invalid string literal delimiter",
        )
    })?;
    Ok(CompilerExpression {
        kind: CompilerExpressionKind::String(value.to_owned()),
        value_type: CompilerType::String,
        int_range: None,
        rational_value: None,
        span: literal,
    })
}

fn exact_string_empty_discard(
    source: &SourceText,
    parameter: &FunctionParameter,
    statement: &Statement,
) -> Option<CompilerStatement> {
    let Statement::Discard {
        value:
            Expression::Application {
                items,
                span: predicate_span,
            },
        ..
    } = statement
    else {
        return None;
    };
    let [
        Expression::Identifier(operation),
        Expression::Identifier(operand),
    ] = items.as_slice()
    else {
        return None;
    };
    if source.slice(*operation) != "empty?"
        || source.slice(*operand) != source.slice(parameter.name)
    {
        return None;
    }
    Some(CompilerStatement::Discard(CompilerExpression {
        kind: CompilerExpressionKind::StringEmptyPredicate(Box::new(CompilerExpression {
            kind: CompilerExpressionKind::Local(source.slice(*operand).to_owned()),
            value_type: CompilerType::String,
            int_range: None,
            rational_value: None,
            span: *operand,
        })),
        value_type: CompilerType::Boolean,
        int_range: None,
        rational_value: None,
        span: *predicate_span,
    }))
}

struct ExactValueGeneratorBody {
    yields: Vec<CompilerGeneratorYield>,
    continuations: Vec<CompilerGeneratorContinuation>,
    explicit_return: Option<Span>,
    result: CompilerExpression,
}

#[allow(clippy::too_many_lines)] // Exact yield/continuation phase proof stays fail-closed together.
fn exact_string_value_generator_body(
    source: &SourceText,
    parameter: &FunctionParameter,
    result_classifier: Span,
    body: &[Statement],
    span: Span,
) -> Result<ExactValueGeneratorBody, Diagnostic> {
    let Some((final_statement, yield_statements)) = body.split_last() else {
        return Err(unsupported(
            source,
            span,
            "String-value custom generator without a final expression",
        ));
    };
    let (result, explicit_return) = match (source.slice(result_classifier), final_statement) {
        ("Unit", Statement::Expression(Expression::Unit(result_span))) => {
            (unit_expression(*result_span), None)
        }
        ("String", Statement::Expression(Expression::String(literal))) => {
            (exact_string_literal_expression(source, *literal)?, None)
        }
        (
            "String",
            Statement::Return {
                keyword,
                value: Expression::String(literal),
            },
        ) => (
            exact_string_literal_expression(source, *literal)?,
            Some(*keyword),
        ),
        _ => {
            return Err(unsupported(
                source,
                statement_span(final_statement),
                "String-value custom generator final expression outside its declared exact Unit or String result",
            ));
        }
    };
    if explicit_return.is_some() && yield_statements.is_empty() {
        return Ok(ExactValueGeneratorBody {
            yields: Vec::new(),
            continuations: Vec::new(),
            explicit_return,
            result,
        });
    }
    if yield_statements.is_empty() {
        return Err(unsupported(
            source,
            span,
            "String-yield custom generator without a suspension",
        ));
    }
    let mut yields = Vec::with_capacity(yield_statements.len());
    let mut continuations = Vec::new();
    for statement in yield_statements {
        if let Some(discard) = exact_string_empty_discard(source, parameter, statement) {
            if result.value_type != CompilerType::Unit
                || yields.is_empty()
                || !continuations.is_empty()
            {
                return Err(unsupported(
                    source,
                    statement_span(statement),
                    "String-yield custom generator outside one discarded empty? initial computation after a suspension",
                ));
            }
            let continuation_span = statement_span(statement);
            continuations.push(CompilerGeneratorContinuation {
                after_resumptions: yields.len(),
                body: CompilerBlock {
                    statements: vec![discard],
                    result: unit_expression(continuation_span),
                },
            });
            continue;
        }
        let Statement::Discard {
            value:
                Expression::Application {
                    items,
                    span: yield_span,
                },
            ..
        } = statement
        else {
            return Err(unsupported(
                source,
                span,
                "String-yield custom generator outside consecutive discarded yields",
            ));
        };
        let [Expression::Identifier(operation), value] = items.as_slice() else {
            return Err(unsupported(
                source,
                *yield_span,
                "String-yield custom generator yield expression",
            ));
        };
        if source.slice(*operation) != "yield" {
            return Err(unsupported(
                source,
                *yield_span,
                "String-yield custom generator outside consecutive discarded yields",
            ));
        }
        match value {
            Expression::Identifier(name) if source.slice(*name) == source.slice(parameter.name) => {
                yields.push(CompilerGeneratorYield::Initial(*yield_span));
            }
            Expression::String(literal) => {
                yields.push(CompilerGeneratorYield::Value(Box::new(
                    exact_string_literal_expression(source, *literal)?,
                )));
            }
            _ => {
                return Err(unsupported(
                    source,
                    value.span(),
                    "String-yield custom generator value outside its initial input or an exact literal",
                ));
            }
        }
    }
    if continuations
        .last()
        .is_some_and(|continuation| continuation.after_resumptions == yields.len())
    {
        return Err(unsupported(
            source,
            span,
            "String-yield custom generator discarded computation without a following suspension",
        ));
    }
    if explicit_return.is_some()
        && !matches!(yields.as_slice(), [CompilerGeneratorYield::Initial(_)])
    {
        return Err(unsupported(
            source,
            span,
            "explicit String return outside exactly one initial-parameter suspension",
        ));
    }
    Ok(ExactValueGeneratorBody {
        yields,
        continuations,
        explicit_return,
        result,
    })
}

fn exact_boolean_value_generator_body(
    source: &SourceText,
    parameter: &FunctionParameter,
    result_classifier: Span,
    body: &[Statement],
    span: Span,
) -> Result<ExactValueGeneratorBody, Diagnostic> {
    let [
        Statement::Discard {
            value:
                Expression::Application {
                    items: yield_items,
                    span: yield_span,
                },
            ..
        },
        Statement::Expression(result_expression),
    ] = body
    else {
        return Err(unsupported(
            source,
            span,
            "Boolean-yield custom generator outside one initial yield and an admitted final expression",
        ));
    };
    let [
        Expression::Identifier(yield_operation),
        Expression::Identifier(yield_value),
    ] = yield_items.as_slice()
    else {
        return Err(unsupported(
            source,
            *yield_span,
            "Boolean-value custom generator yield outside its initial parameter",
        ));
    };
    if source.slice(*yield_operation) != "yield"
        || source.slice(*yield_value) != source.slice(parameter.name)
    {
        return Err(unsupported(
            source,
            span,
            "Boolean-yield custom generator outside yield initial",
        ));
    }
    let initial = CompilerExpression {
        kind: CompilerExpressionKind::Local(source.slice(parameter.name).to_owned()),
        value_type: CompilerType::Boolean,
        int_range: None,
        rational_value: None,
        span: parameter.name,
    };
    let result = exact_boolean_generator_result(
        source,
        parameter,
        result_classifier,
        result_expression,
        initial,
    )?;
    Ok(ExactValueGeneratorBody {
        yields: vec![CompilerGeneratorYield::Initial(*yield_span)],
        continuations: Vec::new(),
        explicit_return: None,
        result,
    })
}

#[allow(clippy::too_many_lines)] // Exact local declarations and fail-closed shape checks stay together.
fn exact_boolean_local_function_generator_body(
    source: &SourceText,
    parameter: &FunctionParameter,
    body: &[Statement],
    span: Span,
) -> Result<(ExactValueGeneratorBody, CompilerFunction), Diagnostic> {
    let [
        enum_statement,
        function_statement,
        yield_statement,
        final_statement,
    ] = body
    else {
        return Err(unsupported(
            source,
            span,
            "Boolean-yield generator-local declaration body outside one enum, function, initial yield, and final call",
        ));
    };
    let Some(EnumSource {
        name: enum_name,
        alternatives,
        ..
    }) = enum_declaration(source, enum_statement)
    else {
        return Err(unsupported(
            source,
            span,
            "generator-local enum declaration",
        ));
    };
    if source.slice(enum_name) != "Choice"
        || alternatives.len() != 2
        || alternatives[0].0 != "Accepted"
        || alternatives[1].0 != "Rejected"
    {
        return Err(unsupported(
            source,
            enum_name,
            "generator-local enum outside Choice (Accepted, Rejected)",
        ));
    }
    let enumeration = CompilerEnumType {
        name: String::from("Choice"),
        alternatives: vec![String::from("Accepted"), String::from("Rejected")],
    };
    let Statement::Function {
        name: function_name,
        is_static: false,
        parameters,
        result,
        effect_bound: None,
        clauses,
        body: function_body,
        span: function_span,
    } = function_statement
    else {
        return Err(unsupported(
            source,
            statement_span(function_statement),
            "generator-local function declaration",
        ));
    };
    let [function_parameter] = parameters.as_slice() else {
        return Err(unsupported(
            source,
            *function_span,
            "generator-local function arity",
        ));
    };
    if source.slice(*function_name) != "label"
        || !function_parameter.fields.is_empty()
        || function_parameter.default.is_some()
        || function_parameter.qualifier.is_some()
        || source.slice(function_parameter.name) != "value"
        || source.slice(function_parameter.classifier) != "Choice"
        || source.slice(*result) != "String"
        || **clauses != FunctionClauses::default()
    {
        return Err(unsupported(
            source,
            *function_span,
            "generator-local function outside label (value : Choice) -> String",
        ));
    }
    let [
        Statement::Expression(Expression::DecisionTable {
            subject,
            rules,
            span: decision_span,
        }),
    ] = function_body.as_slice()
    else {
        return Err(unsupported(
            source,
            *function_span,
            "generator-local label body",
        ));
    };
    let Expression::Identifier(subject_name) = subject.as_ref() else {
        return Err(unsupported(
            source,
            subject.span(),
            "generator-local label decision subject",
        ));
    };
    let [accepted_rule, rejected_rule] = rules.as_slice() else {
        return Err(unsupported(
            source,
            *decision_span,
            "generator-local label decision rules",
        ));
    };
    let (
        DecisionMatcher::Identifier(accepted_matcher),
        Expression::String(accepted_literal),
        DecisionMatcher::Identifier(rejected_matcher),
        Expression::String(rejected_literal),
    ) = (
        &accepted_rule.matcher,
        &accepted_rule.action,
        &rejected_rule.matcher,
        &rejected_rule.action,
    )
    else {
        return Err(unsupported(
            source,
            *decision_span,
            "generator-local label decision shape",
        ));
    };
    let accepted = exact_string_literal_expression(source, *accepted_literal)?;
    let rejected = exact_string_literal_expression(source, *rejected_literal)?;
    if source.slice(*subject_name) != "value"
        || source.slice(*accepted_matcher) != "Accepted"
        || source.slice(*rejected_matcher) != "Rejected"
        || exact_string(&accepted).as_deref() != Some("accepted")
        || exact_string(&rejected).as_deref() != Some("rejected")
    {
        return Err(unsupported(
            source,
            *decision_span,
            "generator-local label decision outside the retained Choice mapping",
        ));
    }
    let Statement::Discard {
        value:
            Expression::Application {
                items: yield_items,
                span: yield_span,
            },
        ..
    } = yield_statement
    else {
        return Err(unsupported(
            source,
            statement_span(yield_statement),
            "generator-local initial yield",
        ));
    };
    let [
        Expression::Identifier(yield_operation),
        Expression::Identifier(yield_value),
    ] = yield_items.as_slice()
    else {
        return Err(unsupported(
            source,
            *yield_span,
            "generator-local initial yield",
        ));
    };
    if source.slice(*yield_operation) != "yield"
        || source.slice(*yield_value) != source.slice(parameter.name)
    {
        return Err(unsupported(
            source,
            *yield_span,
            "generator-local initial yield",
        ));
    }
    let Statement::Expression(Expression::Application {
        items: final_items,
        span: final_span,
    }) = final_statement
    else {
        return Err(unsupported(
            source,
            statement_span(final_statement),
            "generator-local final call",
        ));
    };
    let [
        Expression::Identifier(final_function),
        Expression::Identifier(final_argument),
    ] = final_items.as_slice()
    else {
        return Err(unsupported(
            source,
            *final_span,
            "generator-local final call",
        ));
    };
    if source.slice(*final_function) != "label" || source.slice(*final_argument) != "Accepted" {
        return Err(unsupported(
            source,
            *final_span,
            "generator-local final call outside label Accepted",
        ));
    }
    let local_parameter = CompilerParameter {
        name: String::from("value"),
        discarded: false,
        source_visible: true,
        value_type: CompilerType::Enum(enumeration.clone()),
        int_range: None,
        span: function_parameter.name,
    };
    let function = CompilerFunction {
        source_name: String::from("label"),
        symbol: String::new(),
        parameters: vec![local_parameter.clone()],
        pattern_identities: Vec::new(),
        result_type: CompilerType::String,
        result_captures: Vec::new(),
        body: CompilerBlock {
            statements: Vec::new(),
            result: CompilerExpression {
                kind: CompilerExpressionKind::EnumDecision {
                    subject: Box::new(CompilerExpression {
                        kind: CompilerExpressionKind::Local(local_parameter.name.clone()),
                        value_type: local_parameter.value_type.clone(),
                        int_range: None,
                        rational_value: None,
                        span: *subject_name,
                    }),
                    rules: vec![
                        CompilerEnumRule {
                            value: 0,
                            action: accepted,
                            span: accepted_rule.span,
                        },
                        CompilerEnumRule {
                            value: 1,
                            action: rejected,
                            span: rejected_rule.span,
                        },
                    ],
                    otherwise: None,
                },
                value_type: CompilerType::String,
                int_range: None,
                rational_value: None,
                span: *decision_span,
            },
        },
        span: *function_span,
        is_static: false,
        declared_effects: None,
    };
    let result = CompilerExpression {
        kind: CompilerExpressionKind::Call {
            symbol: String::new(),
            arguments: vec![CompilerExpression {
                kind: CompilerExpressionKind::Enum(0),
                value_type: CompilerType::Enum(enumeration),
                int_range: None,
                rational_value: None,
                span: *final_argument,
            }],
        },
        value_type: CompilerType::String,
        int_range: None,
        rational_value: None,
        span: *final_span,
    };
    Ok((
        ExactValueGeneratorBody {
            yields: vec![CompilerGeneratorYield::Initial(*yield_span)],
            continuations: Vec::new(),
            explicit_return: None,
            result,
        },
        function,
    ))
}

fn exact_boolean_generator_result(
    source: &SourceText,
    parameter: &FunctionParameter,
    result_classifier: Span,
    result_expression: &Expression,
    initial: CompilerExpression,
) -> Result<CompilerExpression, Diagnostic> {
    match source.slice(result_classifier) {
        "Boolean" => {
            let Expression::Application {
                items: result_items,
                span: result_span,
            } = result_expression
            else {
                return Err(unsupported(
                    source,
                    result_expression.span(),
                    "Boolean-value custom generator final value outside not initial",
                ));
            };
            let [
                Expression::Identifier(not_operation),
                Expression::Identifier(result_value),
            ] = result_items.as_slice()
            else {
                return Err(unsupported(
                    source,
                    *result_span,
                    "Boolean-value custom generator final value outside not initial",
                ));
            };
            if source.slice(*not_operation) != "not"
                || source.slice(*result_value) != source.slice(parameter.name)
            {
                return Err(unsupported(
                    source,
                    *result_span,
                    "Boolean-value custom generator outside yield initial followed by not initial",
                ));
            }
            Ok(CompilerExpression {
                kind: CompilerExpressionKind::Not(Box::new(initial)),
                value_type: CompilerType::Boolean,
                int_range: None,
                rational_value: None,
                span: *result_span,
            })
        }
        "String" => {
            exact_boolean_string_generator_decision(source, parameter, result_expression, initial)
        }
        _ => Err(unsupported(
            source,
            result_classifier,
            "Boolean-yield custom generator result outside Boolean or String",
        )),
    }
}

fn exact_boolean_string_generator_decision(
    source: &SourceText,
    parameter: &FunctionParameter,
    expression: &Expression,
    initial: CompilerExpression,
) -> Result<CompilerExpression, Diagnostic> {
    let Expression::DecisionTable {
        subject,
        rules,
        span,
    } = expression
    else {
        return Err(unsupported(
            source,
            expression.span(),
            "Boolean-yield custom generator final String outside its exact decision",
        ));
    };
    let Expression::Identifier(subject_name) = subject.as_ref() else {
        return Err(unsupported(
            source,
            subject.span(),
            "Boolean-yield custom generator final decision subject",
        ));
    };
    let [when_true_rule, otherwise_rule] = rules.as_slice() else {
        return Err(unsupported(
            source,
            *span,
            "Boolean-yield custom generator final decision rules",
        ));
    };
    let (
        DecisionMatcher::Boolean { value: true, .. },
        Expression::String(when_true_literal),
        DecisionMatcher::Otherwise(_),
        Expression::String(when_false_literal),
    ) = (
        &when_true_rule.matcher,
        &when_true_rule.action,
        &otherwise_rule.matcher,
        &otherwise_rule.action,
    )
    else {
        return Err(unsupported(
            source,
            *span,
            "Boolean-yield custom generator final decision outside true then String followed by otherwise String",
        ));
    };
    let when_true = exact_string_literal_expression(source, *when_true_literal)?;
    let when_false = exact_string_literal_expression(source, *when_false_literal)?;
    if source.slice(*subject_name) != source.slice(parameter.name)
        || exact_string(&when_true).as_deref() != Some("accepted")
        || exact_string(&when_false).as_deref() != Some("rejected")
    {
        return Err(unsupported(
            source,
            *span,
            "Boolean-yield custom generator final decision outside initial, accepted, and rejected",
        ));
    }
    Ok(CompilerExpression {
        kind: CompilerExpressionKind::BooleanDecision {
            subject: Box::new(CompilerExpression {
                span: *subject_name,
                ..initial
            }),
            when_true: Box::new(when_true),
            when_false: Box::new(when_false),
        },
        value_type: CompilerType::String,
        int_range: None,
        rational_value: None,
        span: *span,
    })
}

fn exact_int_comparison_expression(
    source: &SourceText,
    expression: &Expression,
    expected_left: i64,
    expected_right: i64,
    feature: &str,
) -> Result<CompilerExpression, Diagnostic> {
    let Expression::Application { items, span } = expression else {
        return Err(unsupported(source, expression.span(), feature));
    };
    let [
        Expression::Integer(left_span),
        Expression::Callable {
            kind: CallableKind::Compare,
            ..
        },
        Expression::Integer(right_span),
    ] = items.as_slice()
    else {
        return Err(unsupported(source, *span, feature));
    };
    let left_value = parse_integer(source.slice(*left_span));
    let right_value = parse_integer(source.slice(*right_span));
    if left_value.as_ref() != Some(&BigInt::from(expected_left))
        || right_value.as_ref() != Some(&BigInt::from(expected_right))
    {
        return Err(unsupported(source, *span, feature));
    }
    let left = CompilerExpression {
        kind: CompilerExpressionKind::Int(left_value.expect("checked integer literal exists")),
        value_type: CompilerType::Int,
        int_range: Some(IntRange::exact(BigInt::from(expected_left))),
        rational_value: None,
        span: *left_span,
    };
    let right = CompilerExpression {
        kind: CompilerExpressionKind::Int(right_value.expect("checked integer literal exists")),
        value_type: CompilerType::Int,
        int_range: Some(IntRange::exact(BigInt::from(expected_right))),
        rational_value: None,
        span: *right_span,
    };
    Ok(CompilerExpression {
        kind: CompilerExpressionKind::Binary {
            operation: CompilerBinary::Compare,
            left: Box::new(left),
            right: Box::new(right),
        },
        value_type: CompilerType::Comparison,
        int_range: None,
        rational_value: None,
        span: *span,
    })
}

fn exact_comparison_value_generator_body(
    source: &SourceText,
    parameter: &FunctionParameter,
    body: &[Statement],
    span: Span,
) -> Result<ExactValueGeneratorBody, Diagnostic> {
    let [
        Statement::Discard {
            value:
                Expression::Application {
                    items: yield_items,
                    span: yield_span,
                },
            ..
        },
        Statement::Expression(result),
    ] = body
    else {
        return Err(unsupported(
            source,
            span,
            "Comparison-value custom generator outside one initial yield and final 3 <=> 2",
        ));
    };
    let [
        Expression::Identifier(yield_operation),
        Expression::Identifier(yield_value),
    ] = yield_items.as_slice()
    else {
        return Err(unsupported(
            source,
            *yield_span,
            "Comparison-value custom generator yield outside its initial parameter",
        ));
    };
    if source.slice(*yield_operation) != "yield"
        || source.slice(*yield_value) != source.slice(parameter.name)
    {
        return Err(unsupported(
            source,
            span,
            "Comparison-value custom generator outside yield initial followed by 3 <=> 2",
        ));
    }
    let result = exact_int_comparison_expression(
        source,
        result,
        3,
        2,
        "Comparison-value custom generator final expression outside 3 <=> 2",
    )?;
    Ok(ExactValueGeneratorBody {
        yields: vec![CompilerGeneratorYield::Initial(*yield_span)],
        continuations: Vec::new(),
        explicit_return: None,
        result,
    })
}

fn exact_int_comparison_value(expression: &CompilerExpression, left: i64, right: i64) -> bool {
    expression.value_type == CompilerType::Comparison
        && matches!(
            &expression.kind,
            CompilerExpressionKind::Binary {
                operation: CompilerBinary::Compare,
                left: actual_left,
                right: actual_right,
            } if exact_int(actual_left).as_ref() == Some(&BigInt::from(left))
                && exact_int(actual_right).as_ref() == Some(&BigInt::from(right))
        )
}

fn exact_comparison_value_generator_action(
    parameter: &CompilerParameter,
    body: &CompilerBlock,
) -> bool {
    parameter.value_type == CompilerType::Comparison
        && !parameter.discarded
        && matches!(
            body.statements.as_slice(),
            [CompilerStatement::Discard(CompilerExpression {
                kind: CompilerExpressionKind::Binary {
                    operation: CompilerBinary::Equal,
                    left,
                    right,
                },
                ..
            })] if matches!(left.kind, CompilerExpressionKind::Local(ref name)
                if name == &parameter.name)
                && left.value_type == CompilerType::Comparison
                && exact_int_comparison_value(right, 1, 2)
        )
        && matches!(body.result.kind, CompilerExpressionKind::Unit)
}

fn exact_enum_value_generator_body(
    source: &SourceText,
    parameter: &FunctionParameter,
    enumeration: &CompilerEnumType,
    body: &[Statement],
    span: Span,
) -> Result<ExactValueGeneratorBody, Diagnostic> {
    let [
        Statement::Discard {
            value:
                Expression::Application {
                    items: yield_items,
                    span: yield_span,
                },
            ..
        },
        Statement::Expression(Expression::Identifier(result_value)),
    ] = body
    else {
        return Err(unsupported(
            source,
            span,
            "Choice-value custom generator outside one initial yield and final Second",
        ));
    };
    let [
        Expression::Identifier(yield_operation),
        Expression::Identifier(yield_value),
    ] = yield_items.as_slice()
    else {
        return Err(unsupported(
            source,
            *yield_span,
            "Choice-value custom generator yield outside its initial parameter",
        ));
    };
    if enumeration.name != "Choice"
        || enumeration.alternatives != ["First", "Second"]
        || source.slice(*yield_operation) != "yield"
        || source.slice(*yield_value) != source.slice(parameter.name)
        || source.slice(*result_value) != "Second"
    {
        return Err(unsupported(
            source,
            span,
            "Choice-value custom generator outside yield initial followed by Second",
        ));
    }
    Ok(ExactValueGeneratorBody {
        yields: vec![CompilerGeneratorYield::Initial(*yield_span)],
        continuations: Vec::new(),
        explicit_return: None,
        result: CompilerExpression {
            kind: CompilerExpressionKind::Enum(1),
            value_type: CompilerType::Enum(enumeration.clone()),
            int_range: None,
            rational_value: None,
            span: *result_value,
        },
    })
}

fn exact_enum_value_generator_action(parameter: &CompilerParameter, body: &CompilerBlock) -> bool {
    !parameter.discarded
        && matches!(
            body.statements.as_slice(),
            [CompilerStatement::Discard(CompilerExpression {
                kind: CompilerExpressionKind::Binary {
                    operation: CompilerBinary::Equal,
                    left,
                    right,
                },
                ..
            })] if matches!(left.kind, CompilerExpressionKind::Local(ref name)
                if name == &parameter.name)
                && matches!(right.kind, CompilerExpressionKind::Enum(0))
                && right.value_type == parameter.value_type
        )
        && matches!(body.result.kind, CompilerExpressionKind::Unit)
}

fn exact_int_string_product_value_generator_body(
    source: &SourceText,
    parameter: &FunctionParameter,
    body: &[Statement],
    span: Span,
) -> Result<ExactValueGeneratorBody, Diagnostic> {
    let [
        Statement::Discard {
            value:
                Expression::Application {
                    items: yield_items,
                    span: yield_span,
                },
            ..
        },
        Statement::Expression(Expression::Product {
            fields: result_fields,
            span: result_span,
        }),
    ] = body
    else {
        return Err(unsupported(
            source,
            span,
            "(Int, String)-value custom generator outside one initial yield and final (8, \"done\")",
        ));
    };
    let [
        Expression::Identifier(yield_operation),
        Expression::Identifier(yield_value),
    ] = yield_items.as_slice()
    else {
        return Err(unsupported(
            source,
            *yield_span,
            "(Int, String)-value custom generator yield outside its initial parameter",
        ));
    };
    let [int_field, text_field] = result_fields.as_slice() else {
        return Err(unsupported(
            source,
            *result_span,
            "(Int, String)-value custom generator final product arity",
        ));
    };
    let (Expression::Integer(int_literal), Expression::String(text_literal)) =
        (&int_field.value, &text_field.value)
    else {
        return Err(unsupported(
            source,
            *result_span,
            "(Int, String)-value custom generator final product fields",
        ));
    };
    let text = exact_string_literal_expression(source, *text_literal)?;
    if source.slice(*yield_operation) != "yield"
        || source.slice(*yield_value) != source.slice(parameter.name)
        || int_field.label.is_some()
        || text_field.label.is_some()
        || source.slice(*int_literal) != "8"
        || exact_string(&text).as_deref() != Some("done")
    {
        return Err(unsupported(
            source,
            span,
            "(Int, String)-value custom generator outside yield initial followed by (8, \"done\")",
        ));
    }
    let int = CompilerExpression {
        kind: CompilerExpressionKind::Int(BigInt::from(8)),
        value_type: CompilerType::Int,
        int_range: Some(IntRange::exact(BigInt::from(8))),
        rational_value: None,
        span: *int_literal,
    };
    let value_type = CompilerType::Tuple(vec![CompilerType::Int, CompilerType::String]);
    Ok(ExactValueGeneratorBody {
        yields: vec![CompilerGeneratorYield::Initial(*yield_span)],
        continuations: Vec::new(),
        explicit_return: None,
        result: CompilerExpression {
            kind: CompilerExpressionKind::Tuple(vec![int, text]),
            value_type,
            int_range: None,
            rational_value: None,
            span: *result_span,
        },
    })
}

