        let source = "use language (version is v0.1)\nanswer is fn static () -> Int\n  return 40 + 2\n  0\nanswer ()\n";
        let program = analyze_for_compiler(source).unwrap();
        assert_eq!(program.main.result.value_type, CompilerType::Int);
